  /** Record a room decision and its rationale without waking the hierarchy. Cross-group decisions must name every affected group lead in required_confirmations; the decision remains proposed until all of them confirm with team_room_confirm. */
  team_room_decide: {
    room_id: string;
    round_id?: string;
    title: string;
    choice: string;
    rationale: string;
    references?: string[];
    /** Affected group leads. A single-member room may omit this for the host-confirmed compatibility path. */
    required_confirmations?: string[];
  } & Record<string, JsonValue>;
  /** Join a durable room as the current Team member. */
  team_room_join: {
    room_id: string;
    /** Optional member to add; defaults to yourself. */
    member?: string;
  } & Record<string, JsonValue>;
  /** Start one of at most three fixed-order rounds in a room. The host is always included as a participant; when members are omitted or the host is not named, the host is appended last. Each participant gets one main turn plus at most one short clarification. */
  team_room_next: {
    room_id: string;
    topic: string;
    members?: string[];
  } & Record<string, JsonValue>;
  /** Open or reuse a durable Team room. Rooms are the default non-waking channel for peer coordination. */
  team_room_open: {
    room_id: string;
    /** Room type. */
    kind: "group" | "level" | "root" | "task";
    /** Human-readable topic. */
    title?: string;
    /** Initial member names. */
    members?: string[];
    /** Parent room ids whose rounds must close before this room can start a round. Group rooms infer level:1 automatically when it exists. */
    depends_on?: string[];
    /** Optional host override. Only tier 0 may use it with replace_host:true. */
    host?: string;
    /** Replace the host of an existing room. Tier 0 only. */
    replace_host?: boolean;
  } & Record<string, JsonValue>;
  /** Post a fact, proposal, risk or question to a durable room without waking recipients. */
  team_room_post: {
    room_id: string;
    /** Active round; defaults to the room round. */
    round_id?: string;
    kind?: "fact" | "proposal" | "risk" | "question" | "decision-request" | "clarification";
    content: string;
    references?: string[];
  } & Record<string, JsonValue>;
  /** Read the compact room snapshot: current round, decisions, unresolved points, evidence, next speaker and pending escalations. Raw transcript is omitted unless explicitly requested. */
  team_room_read: {
    room_id: string;
    /** Include the raw transcript; defaults to false. */
    include_messages?: boolean;
  } & Record<string, JsonValue>;
  /** Resolve one previously recorded unresolved room item with a concrete outcome. The room host or tier 0 only. This keeps stale items from remaining open after downstream work lands. */
  team_room_resolve: {
    room_id: string;
    unresolved_id?: string;
    /** Exact unresolved text when resolving a legacy or id-less item. */
    text?: string;
    /** Concrete outcome or evidence proving the item is resolved. */
    resolution: string;
  } & Record<string, JsonValue>;
  /** Record one durable room-timeout repair event. Retry the current speaker, wake/replace the host for an awaiting-close round, or tier-0 force-close after the bounded close grace. This never reassigns tasks or wakes the whole Team. */
  team_room_timeout_recover: {
    room_id: string;
    round_id?: string;
    /** Retry a speaker, wake/replace the close host, record a stall, or force-close an impossible round. */
    action?: "retry-speaker" | "record-stall" | "wake-host" | "replace-host" | "force-close";
    /** Concrete recovery or stall reason. */
    reason: string;
    references?: string[];
    /** replace-host: a room member that accepts close responsibility. */
    new_host?: string;
    /** force-close: optional round summary; defaults to a deterministic recovery summary. */
    summary?: string;
  } & Record<string, JsonValue>;
  /** Acquire, heartbeat or release the one active execution lease for the current member. */
  team_run_lease: {
    action: "acquire" | "heartbeat" | "release";
    run_id?: string;
    task_id?: string;
    checkpoint?: string;
    expires_at?: number;
    dispatch_id?: string;
    status?: "completed" | "blocked" | "cancelled" | "expired" | "failed";
    error?: string;
  } & Record<string, JsonValue>;
  /** Create one pending task with an explicit deliverable kind and an optional owner. Use the returned id verbatim; never infer the next id from a numeric sequence. discussion/review tasks use no write scopes and close with evidence; edit tasks require write scopes and the plan/commit gate. */
  team_task_create: {
    /** Concise task title. */
    subject: string;
    /** Complete task details and acceptance criteria. */
    description: string;
    /** discussion/review produce evidence without writes; edit produces tracked file changes. */
    kind: "discussion" | "review" | "edit";
    /** Task ids that must complete first. Use boardId:taskId for a cross-board dependency. */
    blocked_by?: string[];
    /** Dependency release threshold. Defaults to accepted; completed selects content completion without waiting for final acceptance. */
    dependency_phase?: "completed" | "draft" | "room-discussion" | "plan-proposed" | "plan-approved" | "execution" | "member-check" | "group-check" | "verifier-review" | "integration-ready" | "integrated" | "accepted" | "blocked" | "rejected" | "cancelled" | "expired";
    /** Advisory workspace-relative file or directory prefixes this task expects to modify. */
    write_scopes?: string[];
    /** Optional member name to assign in the same create mutation. Group leads may assign only their own group members or themselves. */
    owner?: string;
    /** Target board: global, level, group, or an exact board id such as group-proto or level-1. Defaults to global. Tier 0 may read every exact board; the verifier may read group boards read-only; other roles remain restricted to their own board. */
    board?: string;
  } & Record<string, JsonValue>;
  /** Read the complete latest value of one task before changing or executing it. */
  team_task_get: {
    /** Default full. Compact is a decision projection, not completion evidence. */
    view?: "compact" | "full";
    /** Optional exact control-plane revision. */
    snapshotRevision?: number;
    /** Task id. */
    task_id: string;
    /** Board to read: global, level, group, or an exact board id such as group-proto or level-1. Defaults to global. Tier 0 may read every exact board; the verifier may read group boards read-only; other roles remain restricted to their own board. */
    board?: string;
  } & Record<string, JsonValue>;
  /** List tasks on one board, including readiness, owner, revision, blockers, and write-scope warnings. */
  team_task_list: {
    /** Optional compact decision view; default full. Compact is not completion evidence. */
    view?: "compact" | "full";
    /** Optional exact task ids within the authorized board. */
    taskIds?: string[];
    /** Return tasks updated strictly after this epoch-millisecond timestamp. */
    changed_since?: number;
    /** Optional exact control-plane revision; a changed snapshot is refused. */
    snapshotRevision?: number;
    /** Optional exact status filter. */
    status?: "pending" | "in_progress" | "completed";
    /** Optional member-name filter; use unowned for tasks without an owner. */
    owner?: string;
    /** Optional readiness filter. */
    ready?: boolean;
    /** Zero-based result offset. Defaults to 0. */
    cursor?: number;
    /** Number of rows, 1 through 100. Defaults to 50. */
    limit?: number;
    /** Board to read: global, level, group, or an exact board id such as group-proto or level-1. Defaults to global. Tier 0 may read every exact board; the verifier may read group boards read-only; other roles remain restricted to their own board. */
    board?: string;
  } & Record<string, JsonValue>;
  /** Tier-0-only bookkeeping repair for a stranded REFERENCE task. It may complete only by linking to an already completed same-Team task that carries the exact commit and evidence; it never fabricates evidence or bypasses an execution gate. */
  team_task_reconcile: {
    task_id: string;
    /** Completed group-board task whose delivery this reference task represents. */
    source_task_id: string;
    reason: string;
    /** Target board: global, level, group, or an exact board id such as group-proto or level-1. Defaults to global. */
    board?: string;
  } & Record<string, JsonValue>;
  /** Compare-and-set one task action using the latest revision. Tier 0 may reassign any task; a group lead may reassign a task in its own group to one of its tier-2 members when the current owner is not running or the task is dependency-blocked and cannot be in flight. A group lead may also repair write_scopes on an unplanned own-group task when its owner is inactive and no run lease is active; plan-controlled scopes still require replacing the plan. reopen also recovers rejected/cancelled/expired phases. bind_fix repairs the commit/evidence pointers of a completed card without changing its phase or status. The global board accepts mutations from tier 0 only. */
  team_task_update: {
    /** Task id. */
    task_id: string;
    /** Current task revision used as the CAS precondition. */
    expected_revision: number;
    /** Task transition to apply. admin_close is a tier-0-only audit recovery for stranded global reference cards. bind_fix is a narrow completed-card ledger repair. */
    action: "claim" | "release" | "edit" | "set_dependencies" | "complete" | "reopen" | "reassign" | "delete" | "advance_phase" | "admin_close" | "bind_fix";
    /** Next durable task phase for advance_phase. */
    phase?: "draft" | "room-discussion" | "plan-proposed" | "plan-approved" | "execution" | "member-check" | "group-check" | "verifier-review" | "integration-ready" | "integrated" | "accepted" | "blocked" | "rejected" | "cancelled" | "expired";
    /** Replacement title for edit. */
    subject?: string;
    /** Replacement details for edit. */
    description?: string;
    /** Replacement contract goal for edit. */
    goal?: string;
    /** Replacement contract deliverable for edit. */
    deliverable?: string;
    /** Complete blocker list for set_dependencies; boardId:taskId selects a cross-board task. */
    blocked_by?: string[];
    /** Dependency release threshold for set_dependencies. Defaults to accepted; completed releases when each dependency status is completed. */
    dependency_phase?: "completed" | "draft" | "room-discussion" | "plan-proposed" | "plan-approved" | "execution" | "member-check" | "group-check" | "verifier-review" | "integration-ready" | "integrated" | "accepted" | "blocked" | "rejected" | "cancelled" | "expired";
    /** Replacement write scopes for edit. */
    write_scopes?: string[];
    /** Exact commit SHA produced by the task owner when completing it. bind_fix accepts null for a completed card that has no commit. */
    commit_sha?: string | null;
    /** Durable evidence ids proving the completed task. */
    evidence_ids?: string[];
    /** Member name for Lead-only reassign; omit to unassign. */
    owner?: string;
    /** Tier 0 recovery for a global edit card whose owner is inactive. Requires force_complete_reason, exact commit_sha and evidence. */
    force_complete?: boolean;
    /** Audit reason required with force_complete:true. */
    force_complete_reason?: string;
    /** Audit reason required with action:"admin_close". */
    admin_close_reason?: string;
    /** Audit reason required with action:"bind_fix". The action changes only commitSha and evidenceIds on a completed task. */
    bind_fix_reason?: string;
    /** Required with action:"reopen"; stored on the task as lastReopenReason and lastReopenAt. */
    reopen_reason?: string;
    /** Alias for reopen_reason when action is "reopen". */
    reason?: string;
    /** Target board: global, level, group, or an exact board id such as group-proto or level-1. Defaults to global. */
    board?: string;
  } & Record<string, JsonValue>;
  /** Agent Team v12 aggregate control/read tool. Use it for runtime facts, capability gates, task contracts, ready queues, run leases, Room recovery, inbox acknowledgement, compaction state, evidence reuse, merge recovery, context packs, timelines and replay fixtures. Omit action to return compact runtime facts. leases shows the caller's own run leases; tier 0 may inspect any member and a group lead may inspect its own group through input {member}. waiting_list returns active tickets by default; input {includeClosed:true} also returns closurePolicy, closedReason, closedAt and closedBy; use input {ticketId,taskId,offset,limit} for exact or paged reads. failure_memory_status inspects one call signature; failure_memory_clear requires action_fingerprint plus reason and evidence. For inbox_ack, call inbox_list first and pass either the exact top-level wake_id or inbox_id; bulk/all acknowledgement is not supported. */
  team_v12: {
    action?: "runtime_facts" | "capability_matrix" | "upgrade_gate" | "task_contract_get" | "task_contract_set" | "ready_queue" | "scheduler_advice" | "leases" | "control_status" | "control_recover" | "room_snapshot" | "room_migrate" | "room_cursor" | "room_confirm_decision" | "inbox_list" | "inbox_ack" | "requirements_snapshot" | "requirements_diff" | "requirement_record" | "decision_record" | "waiting_set" | "waiting_resolve" | "waiting_list" | "ptc_receipts" | "failure_memory_status" | "failure_memory_clear" | "compaction_status" | "compaction_transition" | "evidence_query" | "review_package" | "verification_plan" | "merge_status" | "merge_recover" | "context_pack" | "timeline" | "replay";
    input?: Record<string, JsonValue>;
    task_id?: string;
    owner?: string;
    board?: string;
    room_id?: string;
    member?: string;
    wake_id?: string;
    inbox_id?: string;
    ticket_id?: string;
    job_id?: string;
    phase?: string;
    confirm?: boolean;
    mode?: string;
  } & Record<string, JsonValue>;
  /** Compatibility alias for send_message(delivery:"action"). Wake one exact Team target for a message that must cause action now. Upward decision wakes must use send_message(delivery:"decision") or the team_wake_superior alias. When task_id is supplied, based_on_revision and based_on_phase are required; stale snapshots are refused. A pending identical sender/target wake is coalesced. */
  team_wake: {
    /** Exact Team member name, or lead where the sender is allowed to reach it. */
    target: string;
    /** Self-contained actionable message for the target. */
    message: string;
    /** Why the target must act now instead of receiving a quiet message. */
    reason: string;
    task_id?: string;
    /** Required with task_id: the exact revision returned by team_task_get immediately before this wake. */
    based_on_revision?: number;
    /** Required with task_id: the exact phase returned by team_task_get immediately before this wake. */
    based_on_phase?: string;
    /** Critical is reserved for safety or data-loss risk. */
    urgency?: "normal" | "high" | "critical";
  } & Record<string, JsonValue>;
  /** Compatibility alias for send_message(delivery:"decision"). Wake your direct superior for a decision that is actually blocked on them. A tier-2 member reaches only its own group lead; a tier-1 lead reaches tier 0. Include the blocked action, reason and evidence. When task_id is supplied, based_on_revision and based_on_phase are required; stale snapshots are refused. A pending wake for the same sender/target is coalesced. */
  team_wake_superior: {
    /** Optional decision summary. The canonical send_message(delivery:"decision") form may omit it because blocked_action, reason and evidence are the required payload. */
    message?: string;
    /** The exact action waiting on the superior. */
    blocked_action: string;
    /** Why this cannot be resolved inside the group or by a normal quiet message. */
    reason: string;
    /** Evidence proving the block or pending decision. */
    evidence: string[];
    task_id?: string;
    /** Required with task_id: the exact revision returned by team_task_get immediately before this wake. */
    based_on_revision?: number;
    /** Required with task_id: the exact phase returned by team_task_get immediately before this wake. */
    based_on_phase?: string;
    /** Optional privilege request awaiting tier-0 review. */
    privilege_request_id?: string;
    /** Critical is reserved for safety or data-loss risk. */
    urgency?: "normal" | "high" | "critical";
  } & Record<string, JsonValue>;
  /** Lay out one member’s git worktree on its integration branch, so two members can never overwrite each other’s files. Tier 0 lays out its group leads, a group lead lays out its own members, and the verifier lays out its own DETACHED (read-only) checkout. On an existing stale worktree this MERGES the requested base into the branch; it never resets or rebases. If a conflict must be resolved without a lease, pass conflict_strategy plus both pinned full commit SHAs; this is the bounded sync channel used to break the acquire/commit deadlock. */
  team_worktree_setup: {
    /** Member whose worktree is created. */
    target: string;
    /** Task whose plan has been approved. */
    task_id: string;
    /** Repository directory the worktrees live under. Defaults to the caller session repository cwd. */
    repo?: string;
    /** Base branch or commit. Defaults to main unless the approved plan explicitly names a fresher base; stale group branches are never selected implicitly. */
    base?: string;
    /** Explicit conflict resolution for a stale member branch: base keeps the requested base side; worktree keeps the member side. Requires expected_head and expected_base. */
    conflict_strategy?: "base" | "worktree";
    /** Full 40-character member branch SHA observed before the conflict resolution. */
    expected_head?: string;
    /** Full 40-character requested base SHA observed before the conflict resolution. */
    expected_base?: string;
  } & Record<string, JsonValue>;
  /** Record and update a task list to plan multi-step work and show progress; skip it for trivial single-step tasks. Add one todo per concrete step before you start. While work remains, keep the todos being worked on `in_progress`, several only when work runs in parallel. Mark each todo `completed` as soon as it is done. */
  todo_write: {
    /** The COMPLETE task list, replacing any previous list. */
    todos: ({
      /** What the task is — a short imperative line. */
      content: string;
      /** pending (not started) | in_progress (now) | completed (done). */
      status: "pending" | "in_progress" | "completed";
    })[];
  } & Record<string, JsonValue>;
  /** Update the current goal. */
  update_goal: {
    /** Exact id returned by get_goal. */
    goal_id: string;
    /** Exact positive revision returned by get_goal. */
    revision: number;
    /** edit, pause, and resume require a direct top-level human request. complete and blocked are also allowed during an automatic continuation of this goal; blocked is rejected before the configured minimum round count. */
    action: "edit" | "pause" | "resume" | "complete" | "blocked";
    /** Replacement objective; valid only with action edit. */
    objective?: string;
    /** Replacement cap; valid only with action edit. */
    max_goal_rounds?: number;
    /** Required only with action blocked: the concrete condition that persisted across rounds and blocks progress. */
    blocked_reason?: string;
  } & Record<string, JsonValue>;
  /** Publish one aggregated issue table. The independent verifier group only. Every issue must cite evidence that distinguishes the broken state; "nothing to report" is not a review. The table is written under the configured report directory and every group lead is notified with the path. A report clears exact commits only when its issue table contains no blocker or major; condition, minor, and nit findings do not suppress clearance. */
  verifier_report: {
    /** Short report name, sanitized to [a-z0-9-_]. Becomes <name>.md in the report directory. */
    name: string;
    /** One-paragraph verdict. */
    summary: string;
    /** Commit hash this verdict was produced against. Required to clear a branch for merge into main; reports with blocker or major do not write clearance keys. */
    commit?: string;
    /** Additional exact commits this report clears, such as both the task commit and the group-branch head. */
    cleared_commits?: string[];
    /** Camel-case alias for cleared_commits. */
    clearedCommits?: string[];
    issues: ({
      severity: "blocker" | "major" | "condition" | "minor" | "nit";
      /** What is wrong. */
      title: string;
      /** The command, file, or output that distinguishes the broken state. */
      evidence: string;
      /** File, symbol, or task id. */
      location?: string;
    })[];
  } & Record<string, JsonValue>;
  /** Rarely needed and NEVER used to wait for a Room turn. When a Room is open, obey team_room_read.waitAction: stop means end the turn and let the system handoff wake you. This tool never wakes inactive members and returns noProgress immediately when no other member is running or provisioning. A return from this call, or the absence of one, is never evidence that a member is stuck. */
  wait_agent: {
    /** Wait duration in milliseconds, from 10000 through 3600000. Defaults to 30000. */
    timeout_ms?: number;
  } & Record<string, JsonValue>;
  /** Fetch the content of a specific HTTP(S) URL and return it decoded to text. */
  web_fetch: {
    /** The HTTP(S) URL to fetch. */
    url: string;
  } & Record<string, JsonValue>;
  /** Search the web for current information. Returns an optional summary answer and a list of source URLs. */
  web_search: {
    /** 1–4 search queries; their results are merged. */
    queries: string[];
  } & Record<string, JsonValue>;
  /** Create or fully replace a UTF-8 text file. */
  write: {
    /** Path to write, resolved by the filesystem backend. */
    file_path: string;
    /** Full UTF-8 text content to write. */
    content: string;
    /** The narrowest wider sandbox mode for a one-shot retry of the exact operation the sandbox just denied; the retry asks the user for approval. */
    sandbox_permissions?: "workspace-write" | "danger-full-access";
    /** Required with sandbox_permissions: one sentence for the user explaining why this exact file operation needs the wider access. Use the language of the user’s current request. */
    justification?: string;
  } & Record<string, JsonValue>;
}

